MovementSystem.Code:

// 1. Xoay để hướng về target
HandleRotation(targetPos, distanceToTarget);

// 2. Di chuyển theo hướng mũi
Vector3 flightDirection = transform.forward;
transform.position += flightDirection * m_flySpeed * Time.deltaTime;

// 3. Kiểm tra đến điểm
if (Vector3.Distance(transform.position, targetPos) <= m_arrivalDistance)
    m_currentPointIndex++;

Event.Usage:

aircraftController.OnAttackTriggered += (attackPoint) => {
    Debug.Log($"Attack triggered at {attackPoint.name}");
    // Spawn explosion, play sound, etc.
};


aircraftController.OnPhaseChanged += (newPhase) => {
    Debug.Log($"Phase changed to {newPhase}");
    // Update UI, play transition effects, etc.
};

CustomAttackLogic.Example:

// Subscribe to attack event
aircraftController.OnAttackTriggered += OnCustomAttack;

private void OnCustomAttack(Transform attackPoint) {
    // Custom attack logic here
    SpawnMissiles(attackPoint.position);
    PlayAttackSound();
    ShowExplosionEffect(attackPoint.position);
}

MultipleAircraft.Example:

// Create aircraft squadron
List<AircraftFlightController> squadron = new List<AircraftFlightController>();

foreach (var aircraft in squadron) {
    aircraft.OnAttackTriggered += OnSquadronAttack;
    aircraft.OnPhaseChanged += OnSquadronPhaseChange;
}

DynamicWaypoints.Example:

// Update waypoints dynamically
var newWaypoint = CreateWaypoint(newPosition);
pointGroup.points.Add(newWaypoint);
pointGroup.UpdatePoints();
